<script setup lang="ts">
import PageShell from '../../components/PageShell.vue';import EmptyState from '../../components/EmptyState.vue';import {usePage} from '../../composables/usePage';import {usePagination} from '../../composables/usePagination';import {request} from '../../utils/request';import {go,time} from '../../utils/format';const pager=usePagination(p=>request('/notifications?page='+p));const {loading,error,load,action}=usePage(()=>pager.load(true));async function read(n:any){await request('/notifications/'+n.id+'/read','POST');n.read_at=new Date().toISOString();if(n.order_id)go('detail/detail?id='+n.order_id)}async function all(){await request('/notifications/read-all','POST');await load()}
</script><template><PageShell title="消息通知" active="notice" :loading="loading" :error="error" @retry="load"><view class="section">每一份安心，及时送达 <text class="link" @click="action(all,'已全部标记已读')">全部已读</text></view><view v-for="n in pager.rows.value" :key="n.id" class="card" @click="action(()=>read(n),'')"><view class="row"><text style="font-weight:700">{{n.read_at?'':'● '}}{{n.title}}</text><text class="muted">{{time(n.created_at)}}</text></view><view class="subtitle">{{n.content}}</view></view><EmptyState v-if="!pager.rows.value.length&&!loading" text="暂无消息，服务进展将在这里通知你"/><button v-if="pager.rows.value.length<pager.total.value" class="outline" @click="action(()=>pager.load(),'')">加载更多</button></PageShell></template>
